fn has_only_one_distinct_element(a: &[i32]) -> bool {
    // An empty array or an array with a single element has only one distinct value
    if a.len() <= 1 {
        return true;
    }

    // Get the first element to compare with the rest
    let first = a[0];

    // Check if all elements are equal to the first element
    for &value in a.iter() {
        if value != first {
            return false; // Found a different element
        }
    }

    true // All elements are equal
}